-- inc1b_contract (docs/pilot/DATA_MODEL.md §3.5, invariants 17-20 in §3.8). Generated by
--   npm run db:new-migration -- inc1b_contract
-- (prisma migrate diff from the Increment 1 schema to prisma/schema.prisma), then hand-edited in the §3.5
-- order: (1) pre-checks, (2) re-derive what the previous release may have written without the inc1a
-- columns, (3) relabel, (4) the generated DDL unchanged, (5) the wallet invariants. The DDL comes after
-- the re-derive because its SET NOT NULLs need those values.
-- It ships one release after inc1a (the first Inc 2 deploy), once only Inc 1 code runs anywhere.
-- The file runs as ONE transaction: if any statement fails, nothing is applied.
--
-- No enum value is added here. REJECTED (added by inc1a, already committed) is safe to use in (3).
-- Every statement in (2) and (3) is safe to re-run and safe on an empty database.

-- (1) PRE-CHECKS [hand edit], in this order. The first that fails stops the file, so the next problem
--     shows on the next run. Each names at most 20 rows, then how many more.

-- 1.1 Every distributor has its one store (distributors.home_store_id SET NOT NULL below).
DO $$
DECLARE bad text; total int;
BEGIN
  SELECT count(*) INTO total FROM distributors WHERE home_store_id IS NULL;
  IF total > 0 THEN
    SELECT string_agg(label, ', ' ORDER BY n) INTO bad FROM (
      SELECT COALESCE(code, 'no code') || ' ' || id::text AS label, row_number() OVER (ORDER BY created_at, id) AS n
      FROM distributors WHERE home_store_id IS NULL) x WHERE n <= 20;
    IF total > 20 THEN bad := bad || ' and ' || (total - 20) || ' more'; END IF;
    RAISE EXCEPTION 'MIGRATION_BLOCKED inc1b: distributors without a store (%). Give each of them its store, run "prisma migrate resolve --rolled-back 20261023112537_inc1b_contract", then deploy again.', bad;
  END IF;
END $$;

-- 1.2 No balance below zero (distributors_balance_chk below).
DO $$
DECLARE bad text; total int;
BEGIN
  SELECT count(*) INTO total FROM distributors WHERE advance_balance_paisa < 0;
  IF total > 0 THEN
    SELECT string_agg(label, ', ' ORDER BY n) INTO bad FROM (
      SELECT COALESCE(code, id::text) || ' ' || advance_balance_paisa::text || ' paisa' AS label,
             row_number() OVER (ORDER BY created_at, id) AS n
      FROM distributors WHERE advance_balance_paisa < 0) x WHERE n <= 20;
    IF total > 20 THEN bad := bad || ' and ' || (total - 20) || ' more'; END IF;
    RAISE EXCEPTION 'MIGRATION_BLOCKED inc1b: distributors with a negative balance (%). Fix with a super-admin correction, run "prisma migrate resolve --rolled-back 20261023112537_inc1b_contract", then deploy again.', bad;
  END IF;
END $$;

-- 1.3 No two customers of one distributor share a phone number (clients_distributor_id_phone_key below).
DO $$
DECLARE bad text; total int;
BEGIN
  SELECT count(*) INTO total FROM (
    SELECT 1 FROM clients GROUP BY distributor_id, phone HAVING count(*) > 1) g;
  IF total > 0 THEN
    SELECT string_agg(label, ', ' ORDER BY n) INTO bad FROM (
      SELECT COALESCE(d.code, d.id::text) || ' ' || c.phone || ' (customers '
               || string_agg(c.id::text, ' ' ORDER BY c.created_at, c.id) || ')' AS label,
             row_number() OVER (ORDER BY d.created_at, d.id, c.phone) AS n
      FROM clients c JOIN distributors d ON d.id = c.distributor_id
      GROUP BY d.id, d.code, d.created_at, c.phone HAVING count(*) > 1) x WHERE n <= 20;
    IF total > 20 THEN bad := bad || ' and ' || (total - 20) || ' more'; END IF;
    RAISE EXCEPTION 'MIGRATION_BLOCKED inc1b: customers of one distributor sharing a phone number (%). Merge or correct them, run "prisma migrate resolve --rolled-back 20261023112537_inc1b_contract", then deploy again.', bad;
  END IF;
END $$;

-- (2) RE-DERIVE [hand edit]: rows the previous release may have written without the inc1a columns
--     (expand and contract, DATA_MODEL §1 rule 6), with the inc1a rules.

-- 2.1 Ledger keys for keyless rows (inc1a 3.6).
UPDATE ledger_entries SET idempotency_key = 'legacy:' || id::text WHERE idempotency_key IS NULL;

-- 2.2 Expense types from the old category, with the inc1a CASE (3.11). An old category first used after
--     inc1a gets its archived LEGACY_ type first. If the office already has a type of that name (the name
--     is taken, expense_types_name_key_key), the expense takes that type instead.
INSERT INTO expense_types (id, code, name, name_key, is_system, sort_order, archived_at, created_at, updated_at)
SELECT gen_random_uuid(), 'LEGACY_' || c, initcap(lower(c)), lower(c), false, 900, now(), now(), now()
FROM (SELECT DISTINCT category::text AS c FROM expenses
      WHERE type_id IS NULL AND category IS NOT NULL AND category::text NOT IN ('FUEL','MAINTENANCE','OTHER')) x
ON CONFLICT DO NOTHING;

UPDATE expenses e SET type_id = t.id FROM expense_types t
WHERE e.type_id IS NULL AND t.code = CASE e.category::text
  WHEN 'FUEL' THEN 'PETROL' WHEN 'MAINTENANCE' THEN 'MAINTENANCE' WHEN 'OTHER' THEN 'OTHER'
  ELSE 'LEGACY_' || e.category::text END;

UPDATE expenses e SET type_id = t.id FROM expense_types t
WHERE e.type_id IS NULL AND e.category IS NOT NULL AND t.name_key = lower(e.category::text);

-- 2.3 Order numbers where missing, continuing per distributor after the highest number and the counter
--     (by created_at, id), then the counter (inc1a 3.2). The counter only ever goes up.
UPDATE orders o SET order_no = x.base + x.rn
FROM (SELECT o2.id,
             row_number() OVER (PARTITION BY o2.distributor_id ORDER BY o2.created_at, o2.id) AS rn,
             GREATEST(COALESCE((SELECT max(m.order_no) FROM orders m WHERE m.distributor_id = o2.distributor_id), 0),
                      d.next_order_no - 1) AS base
      FROM orders o2 JOIN distributors d ON d.id = o2.distributor_id
      WHERE o2.order_no IS NULL) x
WHERE o.id = x.id AND o.order_no IS NULL;

UPDATE distributors d SET next_order_no = m.next
FROM (SELECT distributor_id, max(order_no) + 1 AS next FROM orders GROUP BY distributor_id) m
WHERE m.distributor_id = d.id AND d.next_order_no < m.next;

-- 2.4 Top-up numbers where missing, the same way, then the counter (inc1a 3.5).
UPDATE payments p SET request_no = x.base + x.rn
FROM (SELECT p2.id,
             row_number() OVER (PARTITION BY p2.distributor_id ORDER BY p2.created_at, p2.id) AS rn,
             GREATEST(COALESCE((SELECT max(m.request_no) FROM payments m WHERE m.distributor_id = p2.distributor_id), 0),
                      d.next_topup_no - 1) AS base
      FROM payments p2 JOIN distributors d ON d.id = p2.distributor_id
      WHERE p2.request_no IS NULL) x
WHERE p.id = x.id AND p.request_no IS NULL;

UPDATE distributors d SET next_topup_no = m.next
FROM (SELECT distributor_id, max(request_no) + 1 AS next FROM payments GROUP BY distributor_id) m
WHERE m.distributor_id = d.id AND d.next_topup_no < m.next;

-- 2.5 Distributor codes where missing: the next free D-number after the highest one in use (inc1a 3.1
--     numbered D01, D02... by created_at), in created_at order. A code the office set is never reused.
DO $$
DECLARE r record; k int; candidate text;
BEGIN
  SELECT COALESCE(max(substring(code FROM '^D([0-9]{1,5})$')::int), 0) INTO k FROM distributors WHERE code ~ '^D[0-9]{1,5}$';
  FOR r IN SELECT id FROM distributors WHERE code IS NULL ORDER BY created_at, id LOOP
    LOOP
      k := k + 1;
      candidate := 'D' || lpad(k::text, GREATEST(2, length(k::text)), '0');
      EXIT WHEN NOT EXISTS (SELECT 1 FROM distributors WHERE code = candidate);
    END LOOP;
    UPDATE distributors SET code = candidate WHERE id = r.id;
  END LOOP;
END $$;

-- (3) RELABEL [hand edit]: a refused manual top-up is REJECTED from inc1a on; old ones said FAILED.
UPDATE payments SET status = 'REJECTED' WHERE provider = 'BANK_MANUAL' AND status = 'FAILED';

-- (4) GENERATED DDL (unchanged)
-- DropForeignKey
ALTER TABLE "distributors" DROP CONSTRAINT "distributors_home_store_id_fkey";

-- DropIndex
DROP INDEX "clients_distributor_id_phone_idx";

-- AlterTable
ALTER TABLE "distributors" ALTER COLUMN "code" SET NOT NULL,
ALTER COLUMN "home_store_id" SET NOT NULL;

-- AlterTable
ALTER TABLE "orders" ALTER COLUMN "order_no" SET NOT NULL;

-- AlterTable
ALTER TABLE "payments" ALTER COLUMN "request_no" SET NOT NULL;

-- AlterTable
ALTER TABLE "ledger_entries" ALTER COLUMN "idempotency_key" SET NOT NULL;

-- AlterTable
ALTER TABLE "expenses" ALTER COLUMN "type_id" SET NOT NULL;

-- CreateIndex
CREATE UNIQUE INDEX "clients_distributor_id_phone_key" ON "clients"("distributor_id", "phone");

-- AddForeignKey
ALTER TABLE "distributors" ADD CONSTRAINT "distributors_home_store_id_fkey" FOREIGN KEY ("home_store_id") REFERENCES "stores"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- (5) WALLET INVARIANTS [hand edit]. Prisma never diffs CHECKs, so later migrations keep them.
--     The balance check is validated: pre-check 1.2 proved no balance is below zero. The sign check is
--     NOT VALID: new and updated rows are checked; old rows are left alone.
ALTER TABLE distributors ADD CONSTRAINT distributors_balance_chk CHECK (advance_balance_paisa >= 0);
ALTER TABLE ledger_entries ADD CONSTRAINT ledger_entries_sign_chk CHECK (
     (entry_type IN ('CREDIT_TOPUP','CREDIT_ORDER_REVERSAL') AND amount_paisa > 0)
  OR (entry_type IN ('DEBIT_ORDER','DEBIT_REFILL')           AND amount_paisa < 0)
  OR (entry_type = 'ADJUSTMENT'                              AND amount_paisa <> 0)) NOT VALID;
